#!/bin/sh
# Notice hook for Codex. Generated by Notice; reinstalling hooks rewrites it.
#
# Codex only blocks a PreToolUse call on exit code 2 with the reason on stderr.
# A JSON body with "continue": false is reported as an unsupported field and
# the command still runs, so allowed calls exit 0 with no output, and every
# other event is only forwarded to Notice.
TOKEN_FILE=__TOKEN_FILE__
URL=__URL__
# 1 while the running Notice App predates the variant-aware risk rules: it
# answers "continue" for spellings like `rm -fr /`, so the hook blocks those
# itself instead of asking.
LEGACY_SERVER=__LEGACY_SERVER__
PAYLOAD="$(cat)"

deny() {
  printf 'Notice blocked this command: %s\n' "$1" >&2
  exit 2
}

has() {
  printf '%s' "$1" | /usr/bin/grep -Eq "$2"
}

# Lowercase, turn JSON whitespace escapes and Unicode spaces into spaces, and
# squeeze runs of spaces, as risk.rs does with split_whitespace.
NBSP="$(printf '\302\240')"
IDEO_SPACE="$(printf '\343\200\200')"
FLAT="$(printf '%s' "$PAYLOAD" \
  | LC_ALL=C /usr/bin/sed -e 's/\\[tnr]/ /g' -e "s/$NBSP/ /g" -e "s/$IDEO_SPACE/ /g" \
  | LC_ALL=C /usr/bin/tr '[:upper:]' '[:lower:]' \
  | LC_ALL=C /usr/bin/tr '[:space:]' ' ' \
  | LC_ALL=C /usr/bin/tr -s ' ')"

PRE=0
if has "$FLAT" '"(hook_event_name|hookeventname)" ?: ?"pretooluse"'; then
  PRE=1
fi

DANGER=0
OLD_RULE='rm -rf /|sudo rm|diskutil erase|drop table|truncate table'
if [ "$PRE" = 1 ]; then
  # Words with quotes dropped and `; & | ( )` kept as segment breaks, padded
  # with spaces so every word can be matched as " word ".
  WORDS=" $(printf '%s' "$FLAT" \
    | LC_ALL=C /usr/bin/tr "\\\\\"'\`" '    ' \
    | LC_ALL=C /usr/bin/tr ';&|()' ';;;;;' \
    | LC_ALL=C /usr/bin/sed -e 's/;/ ; /g' \
    | LC_ALL=C /usr/bin/tr -s ' ') "
  ROOT='(/|/\*|~|~/|~/\*|\$home|\$home/|\$home/\*|\$\{home\}|\$\{home\}/|\$\{home\}/\*)'
  RM_ROOT=' ([^ ;]*/)?rm( [^ ;]+)* '"$ROOT"' '
  SUDO_RM=' sudo( [^ ;]+)* ([^ ;]*/)?rm '
  FIND_DELETE=' ([^ ;]*/)?find( [^ ;]+)* (/|~|~/|\$home|\$\{home\})( [^ ;]+)* -delete '
  if has "$FLAT" "$OLD_RULE" || has "$WORDS" "$RM_ROOT" \
    || has "$WORDS" "$SUDO_RM" || has "$WORDS" "$FIND_DELETE"; then
    DANGER=1
  fi
  if [ "$DANGER" = 1 ] && [ "$LEGACY_SERVER" = 1 ] && ! has "$FLAT" "$OLD_RULE"; then
    deny "destructive command; this Notice version cannot ask for approval on this spelling, so run it yourself if it is intended"
  fi
fi

if [ ! -r "$TOKEN_FILE" ]; then
  [ "$DANGER" = 1 ] && deny "Notice token file is missing"
  exit 0
fi
TOKEN="$(cat "$TOKEN_FILE")"

# PreToolUse waits for Notice's answer (approvals time out after 25 seconds);
# Codex kills hooks after the 30 seconds set in config.toml.
MAX_TIME=5
[ "$PRE" = 1 ] && MAX_TIME=28
OUT="$(printf '%s' "$PAYLOAD" | /usr/bin/curl -sS --connect-timeout 1 --max-time "$MAX_TIME" \
  -H "Content-Type: application/json" \
  -H "X-Notice-Token: $TOKEN" \
  -w '\n%{http_code}' \
  --data-binary @- \
  "$URL" 2>/dev/null)"
STATUS=$?

[ "$PRE" = 1 ] || exit 0

if [ "$STATUS" -eq 7 ]; then
  # Notice is not running: only destructive commands are held back.
  [ "$DANGER" = 1 ] && deny "Notice is not running, so this destructive command cannot be approved"
  exit 0
fi
if [ "$STATUS" -ne 0 ]; then
  # A timeout usually means Notice was still waiting on an approval.
  deny "Notice did not answer in time (curl exit $STATUS)"
fi

CODE="$(printf '%s' "$OUT" | /usr/bin/tail -n 1)"
BODY="$(printf '%s' "$OUT" | /usr/bin/sed '$d')"
if [ "$CODE" != 200 ]; then
  [ "$DANGER" = 1 ] && deny "Notice answered HTTP $CODE"
  exit 0
fi
if has "$BODY" '"continue" ?: ?false'; then
  REASON="$(printf '%s' "$BODY" | /usr/bin/sed -n 's/.*"stopReason" *: *"\([^"]*\)".*/\1/p')"
  deny "${REASON:-rejected in Notice}"
fi
if [ "$DANGER" = 1 ] && has "$BODY" 'failed open'; then
  deny "Notice failed while checking this command"
fi
exit 0
